def path(route,fr=False):return ('/fr/' if fr else '/')+route.strip('/')+('/' if route else '')
def image(name,fr=False,cls='',eager=False):
 if name.startswith("criminal-"):
  name=name.replace("criminal-", "criminal-fr-" if fr else "criminal-en-")
  criminal_alts={"criminal-en-hero":"Empty courthouse corridor with tall windows and wooden doors","criminal-en-article":"Blank notebook, pen and closed folio on a wooden desk","criminal-fr-hero":"Salle d’audience vide avec des bancs en bois","criminal-fr-article":"Allée d’une bibliothèque juridique et table de lecture"}
  assetalt[name]=(criminal_alts[name],criminal_alts[name])
 return f'<img class="{cls}" src="/assets/{name}.webp" alt="{assetalt[name][fr]}" width="1536" height="1024" loading="{"eager" if eager else "lazy"}" fetchpriority="{"high" if eager else "auto"}">'
def a(route,label,fr=False,cls=''):return f'<a class="{cls}" href="{path(route,fr)}">{label}</a>'
def button(route,label,fr=False):return a(route,label,fr,'button')
def cards(fr=False,limit=None):
 return '<div class="topic-grid">'+''.join(f'<a id="service-{t[0]}" class="topic-card{' feature-card' if t[0] == 'criminal-law' else ''}" href="{path("topics/"+t[0],fr)}">{image(t[3],fr)}<div><span class="eyebrow">0{i+1}</span><h3>{t[2 if fr else 1]}</h3><p>{t[5 if fr else 4]}</p><span class="text-link">{"VOIR LES SERVICES" if fr else "VIEW LEGAL SERVICES"}</span></div></a>' for i,t in enumerate(topics[:limit]))+'</div>'
