 body=apply_images(body,route,fr)
 body,crumbs=enhance(body,route,title,fr)
 url=origin+path(route,fr); urls.append(url)
 mobile_enquiry=('#enquiry' if route=='contact' else path('contact',fr)+(('?topic='+route.split('/')[-1]) if route.startswith('topics/') else '')+'#enquiry')
 css_version=hashlib.sha256((D/"styles.css").read_bytes()).hexdigest()[:10]
 js_version=hashlib.sha256((D/"app.js").read_bytes()).hexdigest()[:10]
 navigation=''.join(a(x[0],x[2 if fr else 1],fr,'nav-item'+(' active' if route.startswith(x[0]) else '')) for x in nav)
