def intro(k,title,desc,img,fr=False):return f'<section class="page-hero"><div><span class="eyebrow">{k}</span><h1>{title}</h1><p>{desc}</p></div>{image(img,fr,eager=True)}</section>'
def sources(url,fr):return f'<div class="source"><span class="eyebrow">{"RESSOURCE DE RÉFÉRENCE" if fr else "SOURCE & FURTHER READING"}</span><a href="{url}" target="_blank" rel="noopener">{"CONSULTER LA SOURCE" if fr else "VISIT THE SOURCE"}</a><p>{"Vérifiez les détails actuels auprès de l’organisme concerné." if fr else "Confirm current details directly with the relevant organization."}</p></div>'
def callout(fr=False):return f'<section class="callout"><span class="eyebrow">{"VOTRE PROCHAINE ÉTAPE" if fr else "YOUR NEXT STEP"}</span><h2>{"Une bonne question.<br>Un point de départ utile." if fr else "A good question.<br>A useful place to start."}</h2><p>{"Communiquez avec Kostyantyn Mykhalchenko pour discuter de votre dossier, de sa disponibilité et de la prochaine étape." if fr else "Contact Kostyantyn Mykhalchenko to discuss your matter, availability and the next step."}</p>{button("contact","COMMUNIQUER AVEC KOSTYANTYN" if fr else "CONTACT KOSTYANTYN",fr)}</section>'
for fr in (False,True):
 home=f'''<section class="home-hero"><div class="hero-copy"><span class="eyebrow">{'HALIFAX · NOUVELLE-ÉCOSSE' if fr else 'HALIFAX · NOVA SCOTIA'}</span><h1>{'Des conseils juridiques.<br>Une prochaine étape claire.<br><em>À Halifax.</em>' if fr else 'Legal guidance.<br>Clear next steps.<br><em>Here in Halifax.</em>'}</h1><p>{'Kostyantyn Mykhalchenko, avocat et notaire public. Établi à Halifax et au service de clients partout en Nouvelle-Écosse. Rendez-vous en anglais, ukrainien et russe.' if fr else 'Kostyantyn Mykhalchenko, Barrister, Solicitor &amp; Notary Public. Based in Halifax and serving clients across Nova Scotia. Appointments in English, Ukrainian and Russian.'}</p><div class="actions">{button('topics','VOIR LES DOMAINES' if fr else 'VIEW PRACTICE AREAS',fr)}{a('contact','COMMUNIQUER AVEC KOSTYANTYN' if fr else 'CONTACT KOSTYANTYN',fr,'light-link')}</div><div class="hero-note">{'IMMOBILIER. FAMILLE. AFFAIRES. DROIT CRIMINEL.' if fr else 'PROPERTY. FAMILY. BUSINESS. CRIMINAL LAW.'}</div></div><div class="hero-image">{image('review',fr,eager=True)}<div class="image-label"><span>01 /</span> {'COMMENCER PAR L’ESSENTIEL' if fr else 'BEGIN WITH WHAT MATTERS'}</div></div></section><div class="chapter-strip"><span>{'DES REPÈRES POUR LES MOMENTS IMPORTANTS' if fr else 'PRACTICAL STARTING POINTS FOR IMPORTANT MOMENTS'}</span><span>HALIFAX &amp; {'LES ENVIRONS' if fr else 'BEYOND'}</span></div><section class="section"><div class="section-heading"><div><span class="eyebrow">{'LES SUJETS QUI VOUS CONCERNENT' if fr else 'WHAT BRINGS YOU HERE?'}</span><h2>{'Des services pour les décisions importantes.' if fr else 'Legal services for life’s important decisions.'}</h2></div><p>{'Sept domaines. Un contact direct. Discutez de votre dossier avec Kostyantyn et convenez de la prochaine étape.' if fr else 'Seven practice areas. One direct point of contact. Discuss your matter with Kostyantyn and agree on the next step.'}</p></div>{cards(fr)}</section><section class="local-feature"><div>{image('property',fr)}</div><div><span class="eyebrow">{'UNE PERSPECTIVE LOCALE' if fr else 'A LOCAL PERSPECTIVE'}</span><h2>{'D’un côté du port.<br>À l’autre bout de la région.' if fr else 'Across the harbour.<br>Along the shore.<br>Closer to home.'}</h2><p>{'Halifax est une région de quartiers, de banlieues et de collectivités rurales. Le lieu compte pour les déplacements, les dossiers immobiliers et les ressources publiques.' if fr else 'Halifax is a region of neighbourhoods, suburbs and rural communities. Location matters when arranging appointments, finding property information and navigating public resources.'}</p>{button('communities','EXPLORER LES COLLECTIVITÉS' if fr else 'EXPLORE COMMUNITIES',fr)}</div></section><section class="section steps"><div><span class="eyebrow">{'AVANT UN PREMIER ENTRETIEN' if fr else 'BEFORE A FIRST CONVERSATION'}</span><h2>{'Un peu de préparation.<br>Des questions plus précises.' if fr else 'A little preparation.<br>A better conversation.'}</h2></div><ol><li><h3>{'Identifiez le sujet' if fr else 'Name the issue'}</h3><p>{'Notez ce que vous souhaitez comprendre et les dates importantes.' if fr else 'Write down what you want to understand and any important dates.'}</p></li><li><h3>{'Rassemblez les documents' if fr else 'Gather the essentials'}</h3><p>{'Gardez les ententes et avis pertinents ensemble, dans un endroit sûr.' if fr else 'Keep relevant agreements and notices together in a safe place.'}</p></li><li><h3>{'Vérifiez la prochaine étape' if fr else 'Confirm the next step'}</h3><p>{'Discutez de la portée, des honoraires et de la disponibilité avec le professionnel choisi.' if fr else 'Discuss scope, fees and availability with the professional you choose.'}</p></li></ol></section>{callout(fr)}'''
